// Optional independent assembler check. Diagnostics deliberately omit source and generated bytes.
import { existsSync, mkdtempSync, readFileSync, readdirSync, unlinkSync, rmdirSync, writeFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import type { PicAssembly } from '../../src/engine/asmpic';
import type { PicVariant } from '../../src/engine/pic16';
import { readIntelHex } from '../../src/engine/ihex';
const candidates=[process.env.MICROSIM_GPASM,'C:/Program Files/gputils/bin/gpasm.exe','C:/Program Files (x86)/gputils/bin/gpasm.exe','gpasm'].filter((p):p is string=>!!p);
export const gpasm=candidates.find(p=>existsSync(p)||spawnSync(p,['--version'],{windowsHide:true,encoding:'utf8'}).status===0);
export function compareGpasm(assembly:PicAssembly,variant:PicVariant,input:{file:string}|{source:string}){
  if(!gpasm)throw new Error('gpasm is not installed.');
  const dir=mkdtempSync(join(tmpdir(),'microsim-pic-'));
  try{
    const file='file' in input?input.file:join(dir,'original.asm');
    if('source' in input)writeFileSync(file,input.source);
    const output=join(dir,'program.hex');
    const result=spawnSync(gpasm,['-q','-p',variant.slice(3),'-o',output,file],{windowsHide:true,encoding:'utf8'});
    if(result.status!==0||!existsSync(output))throw new Error('gpasm could not assemble the program.');
    const bytes=readIntelHex(readFileSync(output,'utf8'));
    for(const entry of assembly.listing)for(let offset=0;offset<entry.size*2;offset++){
      const at=entry.address*2+offset;
      if(bytes[at]!==assembly.code[at])throw new Error(`gpasm output differs at listing line ${entry.line}.`);
    }
    if(assembly.config!==undefined&&(bytes[0x400e]|(bytes[0x400f]<<8))!==assembly.config)throw new Error('gpasm configuration word differs.');
  }finally{
    // All files in this freshly created, private directory belong to this invocation.
    for(const file of readdirSync(dir))unlinkSync(join(dir,file));rmdirSync(dir);
  }
}
